struct Node;

/// Convert seconds since the Unix epoch (UTC) into a `YYYY-MM-DD` string.
/// Uses the civil-from-days algorithm (Howard Hinnant), so no date crate is needed.
fn format_date(secs: u64) -> String {
    let days = (secs / 86_400) as i64;

    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let day = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let month = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    if month <= 2 {
        year += 1;
    }

    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
